using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml;using BeamScheduleFormatter;
// Run on native Windows; constructs the actual shared UI without Excel.
class ProjectFootingColumnUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why){Check(Math.Abs(a-b)<1e-7,why);}static T Get<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static void Set(object o,string name,object value){o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}static IEnumerable<Control> All(Control root){foreach(Control c in root.Controls){yield return c;foreach(var child in All(c))yield return child;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;string previous=ProjectInfoStore.DirectoryPath,dir=Path.Combine(Path.GetTempPath(),"DTCE-project-ui-"+Guid.NewGuid().ToString("N"));ProjectInfoStore.DirectoryPath=dir;try{
  string title=new string('W',450)+"\nSECOND LINE";ProjectInfoStore.Save(title,"Location");using(var form=new ProjectInformationForm()){form.Show();Application.DoEvents();var box=All(form).OfType<TextBox>().Single(t=>t.MaxLength==2000);Check(box.Multiline&&box.WordWrap&&box.AcceptsReturn,"Project title is a multiline wrapping editor");Check(box.Text.Replace("\r","")==title,"Long saved title displayed in full");form.Width=660;Application.DoEvents();Check(box.Width>400,"Title uses full row on narrow layout");form.Width=1100;Application.DoEvents();Check(box.Width>650,"Title spans both columns on wide layout");form.Close();}
  using(var f=new ProgramOfWorksForm()){Set(f,"filling",true);var g=Get<DataGridView>(f,"footings");for(int i=8;i<20;i++)Check(g.Columns[i].Visible,"Footing reinforcement input visible: "+i);Check(g.Columns[36].Name=="Lean concrete?","Existing lean column index preserved");int n=g.Rows.Add();Check(Convert.ToString(g.Rows[n].Cells[5].Value)=="","New footing quantity starts blank");var row=g.Rows[n];row.Cells[0].Value="F1";row.Cells[1].Value="Footing fixture";row.Cells[2].Value="2";row.Cells[3].Value="2";row.Cells[4].Value=".4";row.Cells[5].Value="1";row.Cells[7].Value="75";row.Cells[8].Value="16";row.Cells[9].Value="150";row.Cells[11].Value="16";row.Cells[12].Value="150";row.Cells[20].Value="0";row.Cells[21].Value="Formed sides";row.Cells[25].Value="28";row.Cells[26].Value="40";row.Cells[27].Value="60";Set(f,"filling",false);f.Recalculate();Check(!row.Cells[9].ReadOnly&&row.Cells[10].ReadOnly,"X spacing active, count inactive");row.Cells["FootingBarMethod0"].Value="Number of bars";Check(Convert.ToString(row.Cells[9].Value)==""&&row.Cells[9].ReadOnly&&!row.Cells[10].ReadOnly,"Changing method clears inactive X spacing");row.Cells[10].Value="8";f.Recalculate();Near(((FootingTakeoff)row.Tag).Steel.Result.Lines.First(l=>l.Part=="Bottom X").PiecesPerBeam,8,"Chosen X quantity drives actual footing computation");Check(!row.Cells[12].ReadOnly&&row.Cells[13].ReadOnly,"Y direction retains independent spacing mode");
   var sheets=Get<Dictionary<string,ExtraWorkGrid>>(f,"extraGrids");var column=sheets["StructuralColumn"];Set(f,"filling",true);int index=column.Grid.Rows.Add();Check(Convert.ToString(column.Grid.Rows[index].Cells[5].Value)=="","New column quantity starts blank");object[] values={"C1","Ground floor",3,300,300,2,16,8,12,0,10,"Spacing (mm)",150,400,false,0};for(int i=0;i<values.Length;i++)column.Grid.Rows[index].Cells[i].Value=values[i];Set(f,"filling",false);f.Recalculate();Check(Get<List<string>>(f,"errors").Count==0,"Footing and column fixtures calculate without errors");var demand=(List<BackupDemand>)Call(f,"BackupQuantities",false);var concrete=demand.Single(d=>d.Key.StartsWith("Concrete pay-item groups|")&&d.Description==BackupPayItemCatalog.Concrete("Structural",false).Description);Near(concrete.Quantity,.54,"Column routes to Structural concrete group");Check(concrete.TargetSlotId!=null&&!concrete.TargetSlotId.StartsWith("missing:"),"Column concrete resolved to actual BACKUP target");
   var extra=(List<BillQuantity>)Call(f,"ExtraBillQuantities");Near(extra.Single(q=>q.Description=="Column Estimate forms").Quantity,7.2,"Column four-face forms reach BOQ");string xml=(string)Call(f,"WorksProjectXml");using(var restored=new ProgramOfWorksForm()){Call(restored,"OpenProjectXml",xml);var fg=Get<DataGridView>(restored,"footings");Check(Convert.ToString(fg.Rows[0].Cells["FootingBarMethod0"].Value)=="Number of bars","Footing mode restored from saved count");Near(Get<List<MiscStructureQuantity>>(restored,"miscQuantities").Single(q=>q.Kind=="Column Estimate").Concrete,.54,"Saved column quantities restored");}
   var doc=new XmlDocument();doc.LoadXml(xml);var table=doc.SelectSingleNode("//ExtraQuantities/Table[@key='StructuralColumn']");table.ParentNode.RemoveChild(table);using(var legacy=new ProgramOfWorksForm()){Call(legacy,"OpenProjectXml",doc.OuterXml);Check(Get<Dictionary<string,ExtraWorkGrid>>(legacy,"extraGrids")["StructuralColumn"].Grid.Rows.Cast<DataGridViewRow>().All(r=>r.IsNewRow),"Earlier projects load with empty new column sheet");}
  }
  Console.WriteLine("PASS: "+checks+" native project, footing, column, BOQ and save/open UI checks");
 }finally{ProjectInfoStore.DirectoryPath=previous;if(Directory.Exists(dir))Directory.Delete(dir,true);}}
}
